import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

// TMDB API anahtarınızı buraya ekleyin
const TMDB_API_KEY = '89ac2e30bf113c90fa3e661683c4c3c4';
const TMDB_BASE_URL = 'https://api.themoviedb.org/3';

function AdvancedSearch() {
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [filters, setFilters] = useState({
    genre: '',
    year: '',
    language: 'tr-TR',
    sortBy: 'popularity.desc'
  });

  // Türleri getir
  const [genres, setGenres] = useState([]);
  useEffect(() => {
    const fetchGenres = async () => {
      try {
        const response = await axios.get(`${TMDB_BASE_URL}/genre/tv/list`, {
          params: {
            api_key: TMDB_API_KEY,
            language: 'tr-TR'
          }
        });
        setGenres(response.data.genres);
      } catch (error) {
        console.error('Türler alınırken hata oluştu:', error);
      }
    };

    fetchGenres();
  }, []);

  // Arama yap
  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setError(null);

    try {
      const params = {
        api_key: TMDB_API_KEY,
        query: query,
        language: filters.language,
        sort_by: filters.sortBy,
        first_air_date_year: filters.year || undefined,
        with_genres: filters.genre || undefined
      };

      const response = await axios.get(`${TMDB_BASE_URL}/search/tv`, { params });
      setResults(response.data.results);
    } catch (error) {
      console.error('Arama yapılırken hata oluştu:', error);
      setError('Arama yapılırken bir hata oluştu. Lütfen tekrar deneyin.');
    } finally {
      setLoading(false);
    }
  };

  // Filtre değişikliklerini işle
  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // Dizi detay sayfasına git
  const goToSeriesDetail = (series) => {
    // Önce diziyi Firebase'e ekle veya güncelle
    // Sonra detay sayfasına yönlendir
    navigate(`/series/${series.id}`);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-pink-50 py-8 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg overflow-hidden">
          {/* Arama Formu */}
          <div className="p-6 border-b border-gray-200">
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Dizi Ara</h2>
            <form onSubmit={handleSearch} className="space-y-4">
              <div className="flex flex-col md:flex-row gap-4">
                <input
                  type="text"
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  placeholder="Dizi adı, tür, yıl veya açıklama yazın..."
                  className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                />
                <button
                  type="submit"
                  className="px-6 py-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 transition duration-200"
                >
                  Ara
                </button>
              </div>

              {/* Filtreler */}
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <select
                  name="genre"
                  value={filters.genre}
                  onChange={handleFilterChange}
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                >
                  <option value="">Tüm Türler</option>
                  {genres.map(genre => (
                    <option key={genre.id} value={genre.id}>
                      {genre.name}
                    </option>
                  ))}
                </select>

                <select
                  name="year"
                  value={filters.year}
                  onChange={handleFilterChange}
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                >
                  <option value="">Tüm Yıllar</option>
                  {Array.from({ length: 24 }, (_, i) => new Date().getFullYear() - i).map(year => (
                    <option key={year} value={year}>{year}</option>
                  ))}
                </select>

                <select
                  name="language"
                  value={filters.language}
                  onChange={handleFilterChange}
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                >
                  <option value="tr-TR">Türkçe</option>
                  <option value="en-US">İngilizce</option>
                </select>

                <select
                  name="sortBy"
                  value={filters.sortBy}
                  onChange={handleFilterChange}
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                >
                  <option value="popularity.desc">Popülerlik (Azalan)</option>
                  <option value="popularity.asc">Popülerlik (Artan)</option>
                  <option value="vote_average.desc">Puan (Azalan)</option>
                  <option value="vote_average.asc">Puan (Artan)</option>
                  <option value="first_air_date.desc">Yayın Tarihi (Yeni)</option>
                  <option value="first_air_date.asc">Yayın Tarihi (Eski)</option>
                </select>
              </div>
            </form>
          </div>

          {/* Sonuçlar */}
          <div className="p-6">
            {loading ? (
              <div className="text-center py-8">
                <div className="animate-spin rounded-full h-12 w-12 border-4 border-purple-500 border-t-transparent mx-auto"></div>
                <p className="mt-4 text-gray-600">Aranıyor...</p>
              </div>
            ) : error ? (
              <div className="text-center py-8 text-red-500">
                <p>{error}</p>
              </div>
            ) : results.length === 0 ? (
              <div className="text-center py-8 text-gray-600">
                <p>Sonuç bulunamadı. Lütfen farklı anahtar kelimeler deneyin.</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                {results.map(series => (
                  <div
                    key={series.id}
                    className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition duration-200 cursor-pointer"
                    onClick={() => goToSeriesDetail(series)}
                  >
                    {series.poster_path ? (
                      <img
                        src={`https://image.tmdb.org/t/p/w500${series.poster_path}`}
                        alt={series.name}
                        className="w-full h-64 object-cover"
                      />
                    ) : (
                      <div className="w-full h-64 bg-gray-200 flex items-center justify-center">
                        <span className="text-gray-400">Görsel yok</span>
                      </div>
                    )}
                    <div className="p-4">
                      <h3 className="font-semibold text-gray-800 mb-1">{series.name}</h3>
                      <p className="text-sm text-gray-600 mb-2">
                        {series.first_air_date ? new Date(series.first_air_date).getFullYear() : 'Yıl bilgisi yok'}
                      </p>
                      <div className="flex items-center">
